<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>فاتورة {{ $invoice->invoice_number }}</title><style>body{font-family:'IBM Plex Sans Arabic',Tahoma,Arial,sans-serif;color:#172033;margin:0;font-size:13px}.page{max-width:190mm;margin:12mm auto}.head{border-bottom:2px solid #e11d48;padding-bottom:12px;display:flex;justify-content:space-between}.muted{color:#64748b}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.box{border:1px solid #e2e8f0;padding:10px;border-radius:6px}.label{display:block;color:#64748b;font-size:11px;margin-bottom:4px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #cbd5e1;padding:8px;text-align:right}th{background:#fff1f2}.totals{width:45%;margin-right:auto;margin-top:16px}.totals div{display:flex;justify-content:space-between;padding:6px;border-bottom:1px solid #e2e8f0}.sign{display:flex;justify-content:space-between;margin-top:50px}.sign div{width:35%;border-top:1px solid #64748b;padding-top:8px;text-align:center}@media print{.page{margin:0;max-width:none}}.head{border-bottom:4px solid #9a4b24;align-items:center}.head h1{color:#66301b;font-size:24px}.grid{grid-template-columns:repeat(2,1fr);gap:8px;margin:14px 0}.box{border:1px solid #b58970;background:#fff8f0;border-radius:4px}.label{color:#704b39}th{background:#66301b;color:#fff}th,td{border:1px solid #b58970}tbody tr:nth-child(even){background:#fff8f0}.totals{width:55%;border:1px solid #b58970}.totals div{border-color:#e7cdbb}.sign{gap:16px;margin-top:40px}.sign div{width:50%;border:1px solid #b58970;border-top:7px solid #66301b;border-radius:4px;padding:16px 4px}@media print{.box,th,tbody tr:nth-child(even){print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style>@include('components.invoice-polish')</head><body><main class="page"><button class="no-print" type="button" onclick="window.print()">طباعة الفاتورة</button><header class="head"><div><h1 style="margin:0">شركة الورود المميزة</h1><p class="muted">هاتف: <span dir="ltr">0925156487</span></p><p>البريد الإلكتروني: <bdi dir="ltr">Mahmoudbushaala4@gmail.com</bdi></p><p class="muted">فاتورة بيع</p></div><div><span class="label">رقم الفاتورة</span><strong dir="ltr">{{ $invoice->invoice_number }}</strong><br><span class="muted">{{ $invoice->invoice_date->format('Y-m-d') }}</span></div></header><section class="grid"><div class="box"><span class="label">حالة الفاتورة</span>{{ match ($invoice->status->value) { 'confirmed' => 'معتمدة', 'cancelled' => 'ملغاة', default => 'مسودة' } }}</div><div class="box"><span class="label">المستلم</span>{{ $invoice->recipient_name ?? '—' }}</div><div class="box"><span class="label">نوع الدفع</span>{{ $invoice->payment_type->value === 'cash' ? 'نقدي' : ($invoice->payment_type->value === 'credit' ? 'آجل' : 'جزئي') }}</div><div class="box"><span class="label">حالة السداد</span>{{ $invoice->payment_status->value === 'paid' ? 'مسددة' : ($invoice->payment_status->value === 'partial' ? 'جزئية' : 'غير مسددة') }}</div></section><table><thead><tr><th>#</th><th>الورد</th><th>اللون</th><th>الوحدة</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->product_name }}</td><td>{{ $item->color ?? '—' }}</td><td>{{ $item->unit }}</td><td>{{ $item->quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->line_total }}</td></tr>@endforeach</tbody></table><section class="totals"><div><span>المجموع الفرعي</span><strong>{{ $invoice->subtotal_amount }}</strong></div><div><span>الخصم</span><strong>{{ $invoice->discount_amount }}</strong></div><div><span>الإجمالي</span><strong>{{ $invoice->total_amount }}</strong></div><div><span>المدفوع</span><strong>{{ $invoice->paid_amount }}</strong></div><div><span>المتبقي</span><strong>{{ $invoice->remaining_amount }}</strong></div></section><section class="sign"><div>توقيع المستلم</div><div>توقيع مسؤول المخزن</div></section></main></body></html>
